begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../fixtures/agenda.psql
update private.bc_finance_settings set simple_mode=true where id;
create temporary table fin_period as select date_trunc('month',now() at time zone 'America/Sao_Paulo')::date start_day,(date_trunc('month',now() at time zone 'America/Sao_Paulo')+interval '1 month - 1 day')::date end_day;
grant select on fin_period to authenticated;
create function pg_temp.fin_overview() returns jsonb language sql as $$select public.bc_finance_overview((select start_day from fin_period),(select end_day from fin_period));$$;
create function pg_temp.fin_report() returns jsonb language sql as $$select public.bc_finance_report((select start_day from fin_period),(select end_day from fin_period));$$;
create function pg_temp.fin_own() returns jsonb language sql as $$select public.bc_finance_my_summary((select start_day from fin_period),(select end_day from fin_period));$$;

select set_config('request.jwt.claim.sub',pg_temp.f('worker')::text,true);
set local role authenticated;
insert into fixture values('simple-appointment',public.bc_agendamento_create(pg_temp.f('client'),pg_temp.f('worker'),pg_temp.f('procedure'),(select slot from test_clock)));
insert into fixture values('simple-treatment',public.bc_treatment_create(pg_temp.f('client'),pg_temp.f('procedure'),pg_temp.f('simple-appointment')));
reset role;
update public.clinical_treatments set final_price=600,status='em_atendimento' where id=pg_temp.f('simple-treatment');
alter table public.clinical_treatment_versions disable trigger bc_external_consent_snapshot_before_version_insert;
insert into public.clinical_treatment_versions(treatment_id,version,snapshot,created_by)
select id,1,jsonb_build_object('treatment',to_jsonb(t)),pg_temp.f('worker') from public.clinical_treatments t where id=pg_temp.f('simple-treatment');
alter table public.clinical_treatment_versions enable trigger bc_external_consent_snapshot_before_version_insert;
update public.clinical_treatments t set current_version_id=v.id from public.clinical_treatment_versions v where v.treatment_id=t.id and t.id=pg_temp.f('simple-treatment');
update public.clinical_treatments set status='finalizado' where id=pg_temp.f('simple-treatment');
insert into fixture select 'simple-attendance',operational_attendance_id from public.clinical_treatments where id=pg_temp.f('simple-treatment');
select is((select valor_total from public.pagamentos where atendimento_id=pg_temp.f('simple-attendance')),600::numeric,'concluir cria obrigação600');
select is((select valor_recebido from public.pagamentos where atendimento_id=pg_temp.f('simple-attendance')),0::numeric,'concluir não inventa recebimento');
select is((select count(*)::integer from public.recebimentos),0,'nenhuma entrada automática');
select ok(exists(select 1 from pg_trigger where tgname='bc_finance_begin_completion' and (tgtype::int & 2)=2),'mutex antecede ponte operacional');
select set_config('request.jwt.claim.sub',pg_temp.f('admin')::text,true);
set local role authenticated;
select is((public.bc_finance_appointment_summary(pg_temp.f('simple-appointment'))->>'remaining')::numeric,600::numeric,'saldo é preenchido pelo servidor');
insert into fixture values('simple-receipt-key',gen_random_uuid());
insert into fixture values('simple-receipt',public.bc_recebimento_registrar_v2(pg_temp.f('simple-receipt-key'),pg_temp.f('simple-attendance'),100,'nao_informado'));
select is(public.bc_recebimento_registrar_v2(pg_temp.f('simple-receipt-key'),pg_temp.f('simple-attendance'),100,'nao_informado'),pg_temp.f('simple-receipt'),'recebimento repetido retorna mesmo UUID');
select is((pg_temp.fin_overview()->>'awaiting_rules')::integer,1,'comissão ausente é pendência explícita');
select is((pg_temp.fin_report()->'totals'->>'income')::numeric,100::numeric,'receita somente confirmada100');
select is((public.bc_finance_appointment_summary(pg_temp.f('simple-appointment'))->>'remaining')::numeric,500::numeric,'parcela preserva saldo500');
select lives_ok(format('select public.bc_finance_commissions_apply(%L,30,array[%L::uuid])',pg_temp.f('worker'),pg_temp.f('procedure')),'regra acordada resolve comissão pendente');
select is((pg_temp.fin_overview()->'pending'->0->>'amount')::numeric,30::numeric,'comissão30 sobre entrada100');
select public.bc_finance_commissions_apply(pg_temp.f('worker'),40,array[pg_temp.f('procedure')]);
insert into fixture values('simple-receipt-2',public.bc_recebimento_registrar_v2(gen_random_uuid(),pg_temp.f('simple-attendance'),200,'nao_informado'));
select is((pg_temp.fin_overview()->'pending'->0->>'amount')::numeric,110::numeric,'snapshot anterior30 preservado, nova comissão80');
reset role;
insert into fixture select 'simple-item',id from private.bc_commission_items where receipt_id=pg_temp.f('simple-receipt');
select is((select count(*)::integer from private.bc_commission_items),2,'um item por recebimento');
set local role authenticated;
select throws_ok(format('select public.bc_finance_commission_pay(gen_random_uuid(),%L,array[%L::uuid],31)',pg_temp.f('worker'),pg_temp.f('simple-item')),'55000',null,'total diferente não é pago');
select throws_ok(format('select public.bc_finance_commission_pay(gen_random_uuid(),%L,array[%L::uuid,%L::uuid],60)',pg_temp.f('worker'),pg_temp.f('simple-item'),pg_temp.f('simple-item')),'22023',null,'seleção duplicada recusada');
insert into fixture values('simple-payment-key',gen_random_uuid());
insert into fixture values('simple-payment',public.bc_finance_commission_pay(pg_temp.f('simple-payment-key'),pg_temp.f('worker'),array[pg_temp.f('simple-item')],30));
select is(public.bc_finance_commission_pay(pg_temp.f('simple-payment-key'),pg_temp.f('worker'),array[pg_temp.f('simple-item')],30),pg_temp.f('simple-payment'),'pagamento repetido não duplica saída');
select is((pg_temp.fin_overview()->'pending'->0->>'amount')::numeric,80::numeric,'pago sai do valor pendente');
select is((pg_temp.fin_report()->'totals'->>'expense')::numeric,30::numeric,'pagamento entra como saída uma vez');
select throws_ok(format('select public.bc_recebimento_estornar(%L,%L)',pg_temp.f('simple-receipt'),'Correção fictícia'),'55000',null,'comissão paga protege recebimento');
select throws_ok(format('select public.bc_livro_fechar(%L,%L::date,%L::date)',pg_temp.f('worker'),date_trunc('week',now() at time zone 'America/Sao_Paulo')::date,date_trunc('week',now() at time zone 'America/Sao_Paulo')::date+6),'55000',null,'modo simples impede fechamento legado');
select lives_ok(format('select public.bc_recebimento_registrar_v2(gen_random_uuid(),%L,100,%L)',pg_temp.f('simple-attendance'),'nao_informado'),'receber após pagar no meio da semana é permitido');
select set_config('request.jwt.claim.sub',pg_temp.f('worker')::text,true);
select is((pg_temp.fin_own()->>'pending_total')::numeric,120::numeric,'colaboradora vê somente saldo ainda devido');
select is((pg_temp.fin_own()->>'paid_total')::numeric,30::numeric,'colaboradora vê pagamento confirmado');
select ok(position('percent' in pg_temp.fin_own()::text)=0 and position('rate_snapshot' in pg_temp.fin_own()::text)=0,'resposta individual não entrega percentual');
select throws_ok(format('select public.bc_finance_commission_pay(gen_random_uuid(),%L,array[%L::uuid],30)',pg_temp.f('worker'),pg_temp.f('simple-item')),'42501',null,'colaboradora não marca pagamento');
select throws_ok('select pg_temp.fin_report()','42501',null,'colaboradora não exporta consolidado');
select throws_ok('select * from private.bc_commission_items','42501',null,'não há leitura bruta de percentuais');
select set_config('request.jwt.claim.sub',pg_temp.f('ordinary')::text,true);
select is((pg_temp.fin_own()->>'pending_total')::numeric,0::numeric,'outra colaboradora não vê valores alheios');
select throws_ok(format('select public.bc_finance_appointment_summary(%L)',pg_temp.f('simple-appointment')),'42501',null,'outra colaboradora não vê cobrança alheia');
select set_config('request.jwt.claim.sub',pg_temp.f('admin')::text,true);
insert into fixture values('simple-expense-key',gen_random_uuid());
insert into fixture values('simple-expense',public.bc_finance_expense_create(pg_temp.f('simple-expense-key'),'Material fictício',25));
select is(public.bc_finance_expense_create(pg_temp.f('simple-expense-key'),'Material fictício',25),pg_temp.f('simple-expense'),'despesa repetida não duplica');
select is((pg_temp.fin_report()->'totals'->>'income')::numeric,400::numeric,'relatório registra entradas400');
select is((pg_temp.fin_report()->'totals'->>'expense')::numeric,55::numeric,'relatório soma comissão30 e despesa25');
select is((pg_temp.fin_report()->'totals'->>'balance')::numeric,345::numeric,'saldo é consistente com movimentos');
select throws_ok(format('select public.bc_finance_expense_create(%L,%L,26)',pg_temp.f('simple-expense-key'),'Material fictício'),'22023',null,'chave não aceita outro valor');
select throws_ok('select public.bc_finance_expense_create(gen_random_uuid(),''Inválido'',''NaN''::numeric)','22023',null,'despesa NaN recusada');
select throws_ok('select public.bc_finance_expense_create(gen_random_uuid(),''Inválido'',1.001)','22023',null,'fração de centavo recusada');
select lives_ok(format('select public.bc_finance_expense_reverse(%L,%L)',pg_temp.f('simple-expense'),'Correção fictícia'),'despesa pode ser cancelada com histórico');
select lives_ok(format('select public.bc_finance_commission_reverse(%L,%L)',pg_temp.f('simple-payment'),'Correção fictícia'),'pagamento pode ser desfeito com histórico');
select is((pg_temp.fin_report()->'totals'->>'expense')::numeric,0::numeric,'cancelados não compõem saída válida');
select is((select count(*)::integer from jsonb_array_elements(pg_temp.fin_report()->'rows') r where not(r->>'included')::boolean),2,'cancelados continuam identificados no resumo');
select lives_ok(format('select public.bc_recebimento_estornar(%L,%L)',pg_temp.f('simple-receipt'),'Correção fictícia'),'após desfazer comissão o recebimento pode ser corrigido');
select is((pg_temp.fin_report()->'totals'->>'income')::numeric,300::numeric,'entrada cancelada fora dos totais');
reset role;
select is((select rate_snapshot from private.bc_commission_items where receipt_id=pg_temp.f('simple-receipt')),30::numeric,'snapshot guardado para histórico');
select is((select count(*)::integer from private.bc_commission_payments),1,'um pagamento confirmado apesar dos retries');
select is((select count(*)::integer from private.bc_finance_expenses),1,'uma despesa apesar dos retries');
update public.staff_profiles set role='admin_criacao',atende_clientes=false,pode_gerenciar_agendas=false,pode_gerenciar_procedimentos=false where user_id=pg_temp.f('ordinary');
select set_config('request.jwt.claim.sub',pg_temp.f('ordinary')::text,true);
set local role authenticated;
select throws_ok('select pg_temp.fin_overview()','42501',null,'criação sem visão financeira');
select throws_ok('select pg_temp.fin_own()','42501',null,'criação sem financeiro individual');
select throws_ok('select pg_temp.fin_report()','42501',null,'criação sem exportação');
select throws_ok('select public.bc_finance_expense_create(gen_random_uuid(),''Inválido'',10)','42501',null,'criação não lança despesa');
reset role;
set local role anon;
select throws_ok('select public.bc_finance_report(current_date,current_date)','42501',null,'anônimo sem execução financeira');
reset role;
select * from finish();
rollback;
